<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    on_trip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">circuit.open</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # event type to emit on trip</span></span>
